fn numpy_append(mut arr: Vec<f32>, values: Vec<f32>) -> Vec<f32> {
    // Pre-allocate enough space for both vectors to avoid repeated re-allocations.
    arr.reserve(values.len());
    // Append all elements of `values` onto the end of `arr`.
    arr.extend(values);
    // Return the concatenated vector.
    arr
}

